//! Session files.
//!
//! Plain, pretty-printed JSON on purpose. Every competing analyzer stores
//! sessions as an opaque binary; a readable file can be diffed, version
//! controlled, generated by a script and fixed by hand.

use serde::{Deserialize, Serialize};

/// Bumped only for a breaking schema change. Additive fields do not bump it,
/// since `serde` defaults cover them.
pub const SESSION_VERSION: u32 = 1;

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub struct SessionSettings {
    pub sample_rate: f32,
    pub fft_size: usize,
    #[serde(default)]
    pub multi_window: bool,
    #[serde(default)]
    pub smoothing: String,
    #[serde(default)]
    pub delay_samples: usize,
    #[serde(default)]
    pub max_averages: usize,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub struct Session {
    pub version: u32,
    pub created_at: String,
    pub name: String,
    pub settings: SessionSettings,
    /// Traces are passed through opaquely: the frontend owns their shape and
    /// this crate has no reason to duplicate it.
    pub traces: Vec<serde_json::Value>,
}

/// Write a session as pretty-printed JSON.
pub fn save_session_to_path(path: &str, session: &Session) -> Result<(), String> {
    let text =
        serde_json::to_string_pretty(session).map_err(|e| format!("serialise session: {e}"))?;
    std::fs::write(path, text).map_err(|e| format!("write {path}: {e}"))
}

/// Read a session, refusing anything this build cannot understand.
pub fn load_session_from_path(path: &str) -> Result<Session, String> {
    let text = std::fs::read_to_string(path).map_err(|e| format!("read {path}: {e}"))?;
    let session: Session =
        serde_json::from_str(&text).map_err(|e| format!("parse {path}: {e}"))?;

    if session.version > SESSION_VERSION {
        return Err(format!(
            "{path} was written by a newer version of Phonetic (session version {}, this build understands {SESSION_VERSION}). Update Phonetic to open it.",
            session.version
        ));
    }

    Ok(session)
}
